SET NAMES utf8mb4;

/* Comparison dimensions are deliberately listing-verifiable and focus on the
   near-substitutes readers actually debate. A missing fact remains unclear. */
INSERT INTO comparison_metric_definitions (category_id,metric_key,label,help_text,comparison_rule,sort_order,is_published)
SELECT c.id,v.metric_key,v.label,v.help_text,'contextual',v.sort_order,TRUE
FROM categories c JOIN (
  SELECT 'pet-grooming-tools' slug,'job' metric_key,'Primary grooming job' label,'A clipper changes coat length, while a de-shedding tool removes loose undercoat; nail care is a separate job.' help_text,1 sort_order UNION ALL
  SELECT 'pet-grooming-tools','power','Power format','Cordless and rechargeable formats improve positioning but still require charging and cooling breaks.',2 UNION ALL
  SELECT 'pet-grooming-tools','pet_fit','Pet and coat fit','Use the exact size, coat, and pet-tolerance boundary stated by the listing.',3 UNION ALL
  SELECT 'pet-grooming-tools','adjustment','Adjustment or guard control','Documented guards or adjustable blades change how much control the handler has.',4 UNION ALL
  SELECT 'pet-grooming-tools','maintenance','Cleaning and maintenance','Blade rinsing, oiling, sanding-band replacement, and heat checks affect ownership.',5 UNION ALL
  SELECT 'pet-waste-cleanup','format','Cleanup format','Pads, mats, bags, and sealed pails solve different waste moments and are not interchangeable.',1 UNION ALL
  SELECT 'pet-waste-cleanup','size','Stated size or coverage','Record the listing dimensions or format instead of inferring usable coverage.',2 UNION ALL
  SELECT 'pet-waste-cleanup','containment','Containment feature','Barriers, waterproof backing, tie handles, or a sealed chute are different containment mechanisms.',3 UNION ALL
  SELECT 'pet-waste-cleanup','cleaning','Cleaning workflow','Disposable, shake/wash, or refill-film workflows create different recurring tasks.',4 UNION ALL
  SELECT 'pet-waste-cleanup','recurring_supply','Recurring supply','Pads, bags, and refill film have different replenishment patterns and costs.',5 UNION ALL
  SELECT 'pet-walking-safety','format','Walking or travel format','Harness, leash, and vehicle-restraint products should be compared by the same job.',1 UNION ALL
  SELECT 'pet-walking-safety','fit','Fit and variant','The exact size, color, and adjustment range are part of product identity.',2 UNION ALL
  SELECT 'pet-walking-safety','attachment','Attachment points','Record the stated leash, handle, or vehicle attachment points; do not infer safety from a name.',3 UNION ALL
  SELECT 'pet-walking-safety','visibility','Visibility feature','Reflective material or trim can help visibility but does not replace a light.',4 UNION ALL
  SELECT 'pet-walking-safety','travel','Vehicle-use context','A walking harness is not automatically a crash restraint; use only the documented vehicle setup.',5
) v ON v.slug=c.slug
ON DUPLICATE KEY UPDATE label=VALUES(label),help_text=VALUES(help_text),sort_order=VALUES(sort_order),is_published=TRUE;

INSERT INTO product_metric_values (product_id,metric_definition_id,display_value,numeric_value,source_url,checked_at,confidence,evidence_status)
SELECT p.id,m.id,v.display_value,v.numeric_value,p.merchant_url,COALESCE(p.commerce_checked_at,NOW()),'limited',v.evidence_status
FROM products p JOIN comparison_metric_definitions m ON m.category_id=p.category_id
JOIN (
  SELECT 'B01HRSZRXM' asin,'job' metric_key,'Coat trimming / clipping' display_value,NULL numeric_value,'explicit' evidence_status UNION ALL SELECT 'B01HRSZRXM','power','Rechargeable cordless',NULL,'explicit' UNION ALL SELECT 'B01HRSZRXM','pet_fit','Dogs; routine home grooming',NULL,'claim' UNION ALL SELECT 'B01HRSZRXM','adjustment','Six guide combs',6,'explicit' UNION ALL SELECT 'B01HRSZRXM','maintenance','Removable, rinsable blade',NULL,'explicit'
  UNION ALL SELECT 'B00EVBXI5S','job','Coat trimming / clipping',NULL,'explicit' UNION ALL SELECT 'B00EVBXI5S','power','Lithium-ion cordless',NULL,'explicit' UNION ALL SELECT 'B00EVBXI5S','pet_fit','Cats and small to medium dogs',NULL,'claim' UNION ALL SELECT 'B00EVBXI5S','adjustment','5-in-1 adjustable blade',5,'explicit' UNION ALL SELECT 'B00EVBXI5S','maintenance','Blade oil and replacement blade care',NULL,'claim'
  UNION ALL SELECT 'B07MZDTG76','job','Loose undercoat de-shedding',NULL,'explicit' UNION ALL SELECT 'B07MZDTG76','power','Manual',NULL,'explicit' UNION ALL SELECT 'B07MZDTG76','pet_fit','Large dogs over 50 lb; long hair',NULL,'claim' UNION ALL SELECT 'B07MZDTG76','adjustment','Size-specific tool',NULL,'explicit' UNION ALL SELECT 'B07MZDTG76','maintenance','Weekly use; brush clean dry coat',NULL,'claim'
  UNION ALL SELECT 'B0DJ3JR93D','job','Nail grinding and trimming',NULL,'explicit' UNION ALL SELECT 'B0DJ3JR93D','power','Cordless rechargeable',NULL,'explicit' UNION ALL SELECT 'B0DJ3JR93D','pet_fit','Dogs, cats, and small animals',NULL,'claim' UNION ALL SELECT 'B0DJ3JR93D','adjustment','Guarded gradual contact',NULL,'claim' UNION ALL SELECT 'B0DJ3JR93D','maintenance','Replaceable sanding bands',NULL,'claim'
  UNION ALL SELECT 'B004GWSIJ8','format','Disposable training pad',NULL,'explicit' UNION ALL SELECT 'B004GWSIJ8','size','27.5 x 44 in',27.5,'explicit' UNION ALL SELECT 'B004GWSIJ8','containment','Runoff barrier edge',NULL,'explicit' UNION ALL SELECT 'B004GWSIJ8','cleaning','Discard after use',NULL,'explicit' UNION ALL SELECT 'B004GWSIJ8','recurring_supply','Pad pack refills',NULL,'explicit'
  UNION ALL SELECT 'B099HBMZ67','format','Washable litter mat',NULL,'explicit' UNION ALL SELECT 'B099HBMZ67','size','28 x 36 in XL',36,'explicit' UNION ALL SELECT 'B099HBMZ67','containment','Waterproof and urine-proof backing',NULL,'claim' UNION ALL SELECT 'B099HBMZ67','cleaning','Machine washable',NULL,'claim' UNION ALL SELECT 'B099HBMZ67','recurring_supply','Reusable; replacement when worn',NULL,'claim'
  UNION ALL SELECT 'B01LZDV5X3','format','Disposable waste bags',NULL,'explicit' UNION ALL SELECT 'B01LZDV5X3','size','Extra-large bags',NULL,'explicit' UNION ALL SELECT 'B01LZDV5X3','containment','Easy-tie handles',NULL,'explicit' UNION ALL SELECT 'B01LZDV5X3','cleaning','Discard after use',NULL,'explicit' UNION ALL SELECT 'B01LZDV5X3','recurring_supply','Bag roll refills',NULL,'explicit'
  UNION ALL SELECT 'B019W0OH48','format','Sealed litter disposal pail',NULL,'explicit' UNION ALL SELECT 'B019W0OH48','size','Up to 14 days for one cat (listing claim)',14,'claim' UNION ALL SELECT 'B019W0OH48','containment','Sealed chute and refill film',NULL,'claim' UNION ALL SELECT 'B019W0OH48','cleaning','Empty and wipe pail',NULL,'claim' UNION ALL SELECT 'B019W0OH48','recurring_supply','14 ft standard refill',14,'explicit'
  UNION ALL SELECT 'B0CLB3VFB8','format','Everyday walking harness',NULL,'explicit' UNION ALL SELECT 'B0CLB3VFB8','fit','Basalt Gray X-Small; four adjustments',4,'explicit' UNION ALL SELECT 'B0CLB3VFB8','attachment','Two leash attachment points',2,'explicit' UNION ALL SELECT 'B0CLB3VFB8','visibility','Reflective trim',NULL,'explicit' UNION ALL SELECT 'B0CLB3VFB8','travel','Walking-first; verify travel setup',NULL,'claim'
  UNION ALL SELECT 'B004IQ6EZ2','format','Everyday walking harness',NULL,'explicit' UNION ALL SELECT 'B004IQ6EZ2','fit','Size 0 Neon Green; match chest range',0,'explicit' UNION ALL SELECT 'B004IQ6EZ2','attachment','Back handle and leash attachment',NULL,'claim' UNION ALL SELECT 'B004IQ6EZ2','visibility','Not stated as reflective in checked facts',NULL,'unclear' UNION ALL SELECT 'B004IQ6EZ2','travel','Walking harness; do not infer crash restraint',NULL,'explicit'
  UNION ALL SELECT 'B0B1F73ZTS','format','5 ft walking leash',5,'explicit' UNION ALL SELECT 'B0B1F73ZTS','fit','Medium, black',NULL,'explicit' UNION ALL SELECT 'B0B1F73ZTS','attachment','Metal clip',NULL,'explicit' UNION ALL SELECT 'B0B1F73ZTS','visibility','Reflective material',NULL,'explicit' UNION ALL SELECT 'B0B1F73ZTS','travel','Walking leash; not a vehicle restraint',NULL,'explicit'
  UNION ALL SELECT 'B0064ACNLO','format','Walking and vehicle-use harness',NULL,'claim' UNION ALL SELECT 'B0064ACNLO','fit','Black Large; dogs up to 75 lb (listing claim)',75,'claim' UNION ALL SELECT 'B0064ACNLO','attachment','Seatbelt tether and steel carabiner',NULL,'explicit' UNION ALL SELECT 'B0064ACNLO','visibility','Not stated as reflective in checked facts',NULL,'unclear' UNION ALL SELECT 'B0064ACNLO','travel','Vehicle-use context stated',NULL,'claim'
) v ON v.asin=p.external_id AND v.metric_key=m.metric_key
ON DUPLICATE KEY UPDATE display_value=VALUES(display_value),numeric_value=VALUES(numeric_value),source_url=VALUES(source_url),checked_at=VALUES(checked_at),confidence=VALUES(confidence),evidence_status=VALUES(evidence_status);

/* Replace cross-purpose comparisons with close, high-interest choices and
   make the article-level decision boundaries explicit. */
UPDATE comparisons SET verdict='Both are everyday dog harnesses; Ruffwear is walking-first, while Kurgo is the more contentious choice when a household also wants a vehicle-use workflow.',content_json=JSON_OBJECT('decisionQuestion','Which tradeoff matters more: walking comfort and visibility, or a walk-plus-travel setup?','scope','The comparison uses the checked Amazon variants: Ruffwear Basalt Gray X-Small and Kurgo black Large. Size and variant are not interchangeable.','controversy','Neither harness is universally safer. Fit, escape risk, attachment point, and the dog’s behavior determine the practical result.','decisionRule','Choose Ruffwear when the daily walk is the primary job; choose Kurgo only when the exact travel instructions and size fit your vehicle routine.','evidenceNote','Listing facts are linked to the live Amazon.com pages; price, stock, seller, and rating can change.') WHERE slug='ruffwear-vs-kurgo-harness';
UPDATE comparisons SET slug='oneisall-vs-wahl-clippers',product_b_id=(SELECT id FROM products WHERE slug='wahl-pro-series-animal'),product_b_name='Wahl Professional Animal Bravura',verdict='Oneisall and Wahl are both cordless clippers, making this the closest grooming comparison: the debate is approachable guards versus adjustable professional-style control.',content_json=JSON_OBJECT('decisionQuestion','Do you value beginner-friendly guard changes or finer blade adjustment and maintenance?','scope','The checked variants are Oneisall B01HRSZRXM and Wahl Bravura B00EVBXI5S; coat condition and pet tolerance remain hard boundaries.','controversy','A quieter or more adjustable clipper does not make a matted coat safe to clip. Heat, pulling, and skin condition can end the session.','decisionRule','Choose Oneisall for routine home trims and guard-led learning; choose Wahl when blade adjustment and maintenance are worth the extra technique.','evidenceNote','Confirm current variant, blade, charger, price, and availability on Amazon.com.') WHERE slug='oneisall-vs-furminator-grooming';
UPDATE comparisons SET verdict='Four Paws pads and Litter Genie are not substitutes, but they are a useful cleanup debate: liquid-accident coverage versus sealed indoor storage of scooped litter.',content_json=JSON_OBJECT('decisionQuestion','Is the recurring failure leakage on a floor or odor and trips from scooped litter?','scope','Pads are a dog liquid-management workflow; Litter Genie is a cat litter-disposal workflow.','controversy','Buying the wrong format creates waste: a pail cannot absorb a floor accident and a pad cannot seal scooped litter.','decisionRule','Choose pads for indoor dog coverage; choose Litter Genie for a litter station with daily scooping and a refill budget.','evidenceNote','Pack count, refill length, price, stock, and variant should be checked on Amazon.com.') WHERE slug='weewee-pads-vs-litter-genie';

/* Rich page bodies: every new article now has a decision boundary, checks,
   alternatives/FAQ, and a source-scope note instead of a one-paragraph stub. */
UPDATE best_picks SET content_json=JSON_OBJECT('why','A focused large-dog, long-hair undercoat tool with a clearly stated weekly-use boundary.','notFor','Matted coats, close trimming, or pets that cannot tolerate brushing.','decision',JSON_OBJECT('headline','Pick by coat problem, not by shedding promises','summary','The listing supports loose-undercoat removal; it does not establish detangling or clipping performance.','criteria',JSON_ARRAY('Correct size and coat length','Light pressure and short sessions','Skin tolerance and stop point'),'boundary','If the coat is matted near skin or the pet reacts to the tool, stop and use professional help.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Why it made the shortlist','body','The checked ASIN is a large-dog, long-hair variant with a weekly de-shedding use case.'),JSON_OBJECT('title','How to decide','body','Compare the dog’s weight, coat length, and tolerance before comparing claims.'),JSON_OBJECT('title','Ownership routine','body','Use on a clean, dry coat; remove collected hair and inspect the skin after each session.'),JSON_OBJECT('title','Alternative path','body','Choose a clipper for length control or a gentle brush for detangling; those are different jobs.')),'alternatives',JSON_ARRAY('A clipper for coat-length changes','A soft brush for detangling'),'evidenceNote','Amazon listing identity and product image are verified; price, stock, seller, and review count remain dynamic.') WHERE slug='best-de-shedding-tool';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A dedicated indoor pail for households that scoop litter daily and want fewer trips to the outside bin.','notFor','Homes unwilling to buy refill film or households whose main problem is liquid floor coverage.','decision',JSON_OBJECT('headline','Choose the waste workflow first','summary','Capacity is a listing claim and varies with cat count, clump size, and emptying cadence.','criteria',JSON_ARRAY('Number of cats and daily scoops','Refill-film availability and cost','Odor and emptying routine'),'boundary','If the refill system is unavailable or the room needs leak protection, choose a different cleanup format.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Why it made the shortlist','body','The checked standard pail includes a 14 ft refill and states up to 14 days for one cat.'),JSON_OBJECT('title','Capacity planning','body','Track a normal week and set an emptying reminder; do not treat the headline capacity as a guarantee.'),JSON_OBJECT('title','Odor control','body','Push waste below the seal, close the chute, and wipe the rim on a regular cadence.'),JSON_OBJECT('title','Alternative path','body','Use sealed disposable bags for portable cleanup or a normal lidded bin when refill film is not practical.')),'alternatives',JSON_ARRAY('Disposable litter bags','A lidded household waste bin'),'evidenceNote','Amazon listing identity is verified; refill price, stock, and current capacity claims must be checked live.') WHERE slug='best-indoor-litter-waste-pail';
UPDATE best_picks SET content_json=JSON_OBJECT('why','The checked Kurgo variant explicitly combines walking and vehicle-use context, with a Large fit boundary and steel hardware.','notFor','Unsupervised vehicle restraint, a guessed size, or dogs whose fit has not been tested while stationary.','decision',JSON_OBJECT('headline','Separate walking fit from travel setup','summary','A travel-capable listing still needs the exact size, attachment path, and current instructions.','criteria',JSON_ARRAY('Chest measurement and variant','Designated vehicle attachment','Stationary fit and movement check'),'boundary','Do not drive until the restraint is correctly installed and tested while parked.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Why it made the shortlist','body','The checked black Large listing states a seatbelt tether, steel carabiner, all-steel buckles, padded chest, and a dog weight claim up to 75 lb.'),JSON_OBJECT('title','Fit before features','body','A harness that rubs, restricts movement, or allows backing out is not a good fit regardless of hardware.'),JSON_OBJECT('title','Travel preflight','body','Check the tether route, buckles, clip, and movement while parked before relying on it in motion.'),JSON_OBJECT('title','Alternative path','body','Choose a walking-first harness when car travel is not part of the routine, or a secured crate when the vehicle setup calls for it.')),'alternatives',JSON_ARRAY('A walking-first padded harness','A secured travel crate'),'evidenceNote','Amazon listing identity and checked variant are verified; current fit guidance and vehicle instructions remain authoritative.') WHERE slug='best-walk-and-travel-harness';

UPDATE guides SET content_json=JSON_OBJECT('summary','A repeatable grooming session is safer when the room, coat, tool, breaks, and stop conditions are prepared before the motor starts.','takeaways',JSON_ARRAY('Brush and inspect the coat first','Run and cool the tool before contact','Use short supervised passes','Stop for heat, pulling, distress, or skin problems'),'sections',JSON_ARRAY(JSON_OBJECT('title','Before the pet arrives','paragraphs',JSON_ARRAY('Charge the cordless tool, fit the guard or correct bit, and place treats, a brush, and a cool surface within reach.','Never begin on a coat with unknown mats close to skin.')),JSON_OBJECT('title','During the session','bullets',JSON_ARRAY('Start away from the pet to gauge sound and vibration.','Check blade or bit temperature frequently.','Work in short passes and reward calm posture.')),JSON_OBJECT('title','Stop and escalate','body','Stop for bleeding, a damaged guard, repeated distress, skin irritation, or a mat that will not release safely. A groomer or veterinarian is the right next step.'),JSON_OBJECT('title','Aftercare','checklist',JSON_ARRAY('Clean the blade or sanding area','Record what the pet tolerated','Store the tool out of reach'))),'faq',JSON_ARRAY(JSON_OBJECT('q','Can a quiet tool handle a matted coat?','a','No. Noise level does not remove the skin and heat risks of mats.'),JSON_OBJECT('q','How long should the first session be?','a','Use the shortest calm session that ends successfully; build duration gradually.'),JSON_OBJECT('q','When is professional help better?','a','When mats are tight to skin, the pet cannot remain calm, or the handler cannot see the skin.')),'sourceNote','Product facts are scoped to the checked Amazon.com listing; safety and health boundaries should be confirmed with a qualified professional.') WHERE slug='pet-grooming-session-safety-checklist';
UPDATE guides SET content_json=JSON_OBJECT('summary','Estimate cleanup from real events, then add leakage, refill delays, and cleaning time instead of comparing package headlines alone.','takeaways',JSON_ARRAY('Count a normal week','Separate liquid, solid, and tracking problems','Include recurring supplies','Set a refill trigger','Keep a backup plan'),'sections',JSON_ARRAY(JSON_OBJECT('title','Count the routine','body','Record pads used, dog-walk bags, litter scoops, and mat wash cycles for seven normal days.'),JSON_OBJECT('title','Calculate the failure cost','table',JSON_ARRAY(JSON_OBJECT('item','Leakage','check','Extra pad, cleaner, and laundry'),JSON_OBJECT('item','Refill delay','check','Backup roll or pack'),JSON_OBJECT('item','Odor','check','Earlier emptying and cleaning'))),JSON_OBJECT('title','Compare formats honestly','body','A washable mat reduces disposable use but does not contain scooped waste. A pail reduces trips but needs refill film.'),JSON_OBJECT('title','Set a trigger','checklist',JSON_ARRAY('Keep one backup roll or pack','Check delivery lead time','Review usage after a pet-count change'))),'faq',JSON_ARRAY(JSON_OBJECT('q','Should I compare price per package?','a','Use cost per week or per event; pack counts and variant sizes differ.'),JSON_OBJECT('q','What changes with multiple pets?','a','Scoops, bags, pads, and emptying frequency rise; capacity claims become less useful.'),JSON_OBJECT('q','What is the cheapest format?','a','The best value is the format that prevents the failure you actually experience.')),'sourceNote','Dimensions and feature claims are tied to checked Amazon listings; prices and pack counts are dynamic.') WHERE slug='pet-waste-cost-and-capacity-planner';
UPDATE guides SET content_json=JSON_OBJECT('summary','A two-minute check of pet fit, clips, leash, visibility, ID, and route catches many preventable failures before a walk.','takeaways',JSON_ARRAY('Fit before leaving','Inspect every load-bearing connection','Carry identification and a backup plan','Adjust for traffic, weather, and visibility'),'sections',JSON_ARRAY(JSON_OBJECT('title','Pet fit','checklist',JSON_ARRAY('Two-finger strap check','No rubbing behind elbows','Dog can breathe and move normally','Current ID tag and contact details')),JSON_OBJECT('title','Equipment fit','checklist',JSON_ARRAY('Buckle fully closed','Clip gate closes','Stitching and webbing intact','Reflective trim or light visible')),JSON_OBJECT('title','Route and backup','body','Carry water, waste bags, and a light. Know where you will go if the dog slips the fit, weather changes, or traffic becomes unsafe.'),JSON_OBJECT('title','Vehicle transition','body','A walking harness is not automatically a crash restraint. Use only the documented vehicle attachment and test it while parked.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is reflective trim enough at night?','a','No. Add a light and choose a visible route.'),JSON_OBJECT('q','How often should clips be checked?','a','Before each walk and after any unusual load or fall.'),JSON_OBJECT('q','Can any harness be used in a car?','a','Only when the exact product instructions document that setup.')),'sourceNote','Variant and feature facts come from checked Amazon listings; fit and travel safety require the current manufacturer instructions.') WHERE slug='dog-walk-safety-preflight';

UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Stop at distress, bleeding, a cracked nail, or a damaged guard. Do not force a session.','intro','Vibration reactions usually improve through acclimation and shorter contact, not by pressing harder.','quickChecks',JSON_ARRAY('Run the motor away from the pet','Inspect guard and sanding band','Confirm the correct speed and bit','Check whether the nail is already cracked'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Build sound tolerance','instruction','Run the grinder nearby for a few seconds, reward calm behavior, and stop before the pet escalates.','why','The sound can be the trigger even before contact.','result','The pet can remain relaxed with the motor on.'),JSON_OBJECT('title','Check the contact surface','instruction','Remove buildup and replace a worn or damaged band; confirm the guard is seated.','why','A rough or damaged surface increases vibration and heat.','result','The tool runs smoothly without visible damage.'),JSON_OBJECT('title','Use one-second contacts','instruction','Touch one nail briefly, reward, and end the session if the pet withdraws.','why','Short exposures reduce heat and help create a predictable routine.','result','The nail is shortened gradually without panic.'),JSON_OBJECT('title','Escalate','instruction','Stop and contact a groomer or veterinarian for bleeding, cracks, pain, or repeated distress.','why','Tool technique cannot solve an injury or severe fear response.','result','The pet receives appropriate professional care.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Pet reacts before contact','cause','Sound or vibration sensitivity','next','Return to sound-only acclimation'),JSON_OBJECT('observation','Tool feels rough','cause','Worn band or buildup','next','Clean or replace the band'),JSON_OBJECT('observation','Nail bleeds','cause','Quick reached','next','Stop and seek advice if bleeding persists')),'support','If the guide does not resolve the problem, use the current Dremel instructions or a qualified groomer.','supportChecklist',JSON_ARRAY('Have the ASIN and tool variant ready','Note bit/band and speed','Record when distress or bleeding occurred'),'faq',JSON_ARRAY(JSON_OBJECT('q','Should I hold the paw tighter?','a','No. Restraint can increase fear and injury risk.'),JSON_OBJECT('q','Can I finish all nails in one sitting?','a','Only if the pet remains calm; several short sessions are acceptable.'),JSON_OBJECT('q','What if the motor sounds abnormal?','a','Stop, inspect the tool, and do not use it while damaged.')),'sourceNote','Product-specific facts are from the checked Amazon listing; injury and behavior questions need qualified professional help.') WHERE slug='dremel-pawcontrol-vibration-too-high';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Wash hands after handling waste, keep the pail inaccessible to pets, and do not reach into a jammed chute.','intro','Odor usually points to a seal, overfill, refill, or cleaning routine issue.','quickChecks',JSON_ARRAY('Confirm the refill film is seated','Push waste below the seal','Check the fill line and chute','Inspect the rim and lid for residue'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Reseat the refill','instruction','Open the top and confirm the standard refill film is seated and the cutter area closes fully.','why','A loose film path can let odor bypass the seal.','result','The lid closes without pinching or gaps.'),JSON_OBJECT('title','Reset the drop routine','instruction','Push each scoop below the seal and close the chute after every use.','why','Waste left above the seal releases odor into the room.','result','The chute area is clear after a test scoop.'),JSON_OBJECT('title','Empty earlier','instruction','Set a shorter cadence for multiple cats or large clumps instead of waiting for maximum capacity.','why','The listing capacity is a one-cat claim and varies in practice.','result','The pail stays below the overfill point.'),JSON_OBJECT('title','Clean contact surfaces','instruction','Wipe the rim and lid with a pet-safe cleaner and dry before closing.','why','Residue can hold odor even when the film is intact.','result','The seal area is clean and dry.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Odor starts after a refill change','cause','Film not seated','next','Reseat and test the seal'),JSON_OBJECT('observation','Odor worsens when full','cause','Overfill or long interval','next','Empty earlier'),JSON_OBJECT('observation','Odor remains when empty','cause','Residue on rim or lid','next','Clean and dry contact surfaces')),'support','If the seal or cutter is damaged, stop using it and consult the current Litter Genie instructions.','supportChecklist',JSON_ARRAY('Record refill type and date','Note cat count and scoop frequency','Photograph any damaged seal'),'faq',JSON_ARRAY(JSON_OBJECT('q','Does the pail eliminate odor?','a','No. It contains waste when used and maintained correctly.'),JSON_OBJECT('q','Can I use any refill?','a','Use the refill format specified for the current pail.'),JSON_OBJECT('q','How often should it be emptied?','a','Use your actual cat count and clump volume rather than the headline claim.')),'sourceNote','Capacity and refill facts are scoped to the checked Amazon listing; current manufacturer instructions control.') WHERE slug='litter-genie-odor-escaping';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Do not use an unfamiliar restraint on a moving vehicle. Park first and follow the current Kurgo instructions for the exact variant.','intro','A twisted clip is usually a routing or fit problem, not a reason to improvise a new attachment point.','quickChecks',JSON_ARRAY('Park before changing anything','Identify the designated vehicle attachment','Check harness orientation and chest fit','Test movement while stationary'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Stop and park','instruction','Move the vehicle to a safe parked position before inspecting the harness or tether.','why','Adjustments should never be made while driving.','result','The pet and vehicle are stationary.'),JSON_OBJECT('title','Confirm the attachment path','instruction','Match the tether and steel carabiner to the designated vehicle-use point in the current instructions.','why','A generic leash point may not be the intended travel path.','result','The tether is routed without twisting or rubbing.'),JSON_OBJECT('title','Recheck fit','instruction','Verify chest strap, buckles, throat clearance, and whether the dog can back out under gentle supervised pressure.','why','Poor fit can rotate the harness and change the clip position.','result','The harness stays aligned while the dog moves.'),JSON_OBJECT('title','Test while parked','instruction','Allow normal sitting and standing movement, then recheck every connection before driving.','why','A stationary test catches rotation before a moving load.','result','The setup remains aligned and secure.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Clip rotates immediately','cause','Harness or tether routed incorrectly','next','Follow the exact attachment path'),JSON_OBJECT('observation','Harness shifts sideways','cause','Loose or mismatched fit','next','Re-measure and adjust'),JSON_OBJECT('observation','Dog backs toward opening','cause','Body shape and fit boundary','next','Stop travel and seek a better fit')),'support','If the current instructions do not match the hardware in hand, contact the manufacturer before driving.','supportChecklist',JSON_ARRAY('Record the exact ASIN and size','Keep the current manual nearby','Test in a parked vehicle first'),'faq',JSON_ARRAY(JSON_OBJECT('q','Can I clip to any metal ring?','a','No. Use only the attachment point documented for the intended use.'),JSON_OBJECT('q','Is a harness automatically crash tested?','a','No. Confirm the exact product and current claim.'),JSON_OBJECT('q','What if the dog can back out?','a','Do not drive; refit or choose a different restraint setup.')),'sourceNote','Vehicle-use claims and variant details are tied to the checked Amazon listing; current manufacturer instructions are authoritative.') WHERE slug='kurgo-harness-car-clip-twists';

/* The first three articles created with the category rollout receive the same
   depth as the later articles above. */
UPDATE best_picks SET content_json=JSON_OBJECT('why','A cordless entry point with six guide combs and a rinsable blade for routine home trims.','notFor','Matted coats, professional daily workloads, or a pet that cannot tolerate clipping.','decision',JSON_OBJECT('headline','Start with control and tolerance','summary','The listing supports guard-led home trimming; it does not prove every coat can be clipped safely.','criteria',JSON_ARRAY('Coat condition','Guide-comb range','Noise and heat tolerance'),'boundary','Stop for pulling, heat, skin irritation, or distress.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked Oneisall ASIN identifies a rechargeable cordless kit with six guide combs and a removable rinsable blade.'),JSON_OBJECT('title','First session','body','Charge, fit a guard, run the motor away from the pet, and make short passes on a brushed coat.'),JSON_OBJECT('title','Tradeoff','body','A guard-led setup is approachable, but it still needs cleaning, blade checks, and realistic coat boundaries.'),JSON_OBJECT('title','Alternative','body','Choose Wahl Bravura when adjustable blade control and maintenance matter more than a simple guard workflow.')),'alternatives',JSON_ARRAY('Wahl Professional Animal Bravura','A professional groomer for close mats'),'evidenceNote','ASIN, image, and listing identity are verified on Amazon.com; dynamic price and stock should be checked live.') WHERE slug='best-quiet-grooming-clipper';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A large 27.5 x 44 inch pad with a stated runoff barrier edge for indoor dog coverage.','notFor','Households trying to eliminate disposable waste or floors where the target area is not covered by the pad.','decision',JSON_OBJECT('headline','Coverage is only useful when placement matches the accident','summary','The dimension and barrier are listing facts; actual leakage depends on placement, saturation, and pet behavior.','criteria',JSON_ARRAY('Usable floor area','Pack usage per week','Edge and runoff risk'),'boundary','If the pad saturates or the pet targets the edge, add overlap or change the routine.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Listing fit','body','The checked variant is 27.5 x 44 inches and includes a runoff barrier edge; confirm pack count before checkout.'),JSON_OBJECT('title','Placement test','body','Lay it flat, absorbent side up, and observe where the dog actually steps and squats.'),JSON_OBJECT('title','Cost check','body','Compare weekly events and cleaner/laundry cost, not only the package price.'),JSON_OBJECT('title','Alternative','body','Use a washable mat for tracking or outdoor breaks when the problem is not liquid containment.')),'alternatives',JSON_ARRAY('Drymate washable litter mat','Outdoor potty routine'),'evidenceNote','Dimensions and feature claims are tied to the checked Amazon variant; pack count and price are dynamic.') WHERE slug='best-large-dog-training-pad';
UPDATE best_picks SET content_json=JSON_OBJECT('why','A padded walking harness with four adjustment points, two leash attachments, and reflective trim in the checked Basalt Gray X-Small variant.','notFor','Dogs whose body shape allows backing out, an unmeasured size, or unsupervised vehicle restraint.','decision',JSON_OBJECT('headline','Fit is the actual feature','summary','Comfort and visibility only help when the exact size stays aligned through movement.','criteria',JSON_ARRAY('Chest measurement','Two-finger clearance','No elbow rub or backing out'),'boundary','Stop outdoor use until the harness is refit if it shifts, rubs, or permits escape.','confidence','moderate'),'sections',JSON_ARRAY(JSON_OBJECT('title','Variant fit','body','The checked listing is Basalt Gray X-Small; do not generalize its fit to larger dogs.'),JSON_OBJECT('title','Adjustment sequence','body','Set the chest and neck straps evenly, then test walking and a gentle supervised backing-out motion indoors.'),JSON_OBJECT('title','Visibility and control','body','Reflective trim helps low light, while the two attachment points should match the intended leash setup.'),JSON_OBJECT('title','Alternative','body','Compare Julius-K9 for a back handle and sturdier control emphasis, or Kurgo when travel is part of the routine.')),'alternatives',JSON_ARRAY('Julius-K9 IDC Powerharness','Kurgo Enhanced Strength Tru-Fit'),'evidenceNote','Variant identity and listed features are checked on Amazon.com; current size charts and travel instructions remain authoritative.') WHERE slug='best-everyday-dog-harness';

UPDATE guides SET content_json=JSON_OBJECT('summary','Choose a clipper by the actual coat, handling skill, noise tolerance, and maintenance routine rather than motor marketing alone.','takeaways',JSON_ARRAY('Identify coat and mat boundaries','Compare guards and blade adjustment','Plan heat and noise breaks','Budget for cleaning and parts'),'sections',JSON_ARRAY(JSON_OBJECT('title','Start with the coat','body','Thick, matted, curly, and fine coats need different guard or blade strategies. Mats close to skin are a stop condition.'),JSON_OBJECT('title','Compare control','table',JSON_ARRAY(JSON_OBJECT('factor','Guards','question','Will the handler use a repeatable length?'),JSON_OBJECT('factor','Adjustable blade','question','Is finer control worth extra maintenance?'),JSON_OBJECT('factor','Noise and heat','question','Can the pet remain calm through a short pass?'))),JSON_OBJECT('title','Run a first session','checklist',JSON_ARRAY('Charge and inspect the tool','Run it away from the pet','Make short passes on a brushed coat','Check skin and blade temperature')),JSON_OBJECT('title','Know when to stop','body','Pulling, heat, damaged hardware, skin irritation, or escalating fear call for a pause and possibly professional help.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is a higher-power clipper always better?','a','No. Control, heat, coat condition, and pet tolerance determine the practical fit.'),JSON_OBJECT('q','What parts need maintenance?','a','Clean and oil blades as directed, charge safely, and plan for guards, blades, or sanding bands.'),JSON_OBJECT('q','Can I clip mats at home?','a','Do not assume so; tight mats can hide skin and should be handled professionally.')),'sourceNote','Product claims are scoped to checked Amazon listings; coat and skin safety should be confirmed with a qualified groomer or veterinarian.') WHERE slug='choose-a-pet-clipper-by-coat-and-temperament';
UPDATE guides SET content_json=JSON_OBJECT('summary','Lower mess comes from matching containment, placement, disposal, and cleaning cadence to the actual waste event.','takeaways',JSON_ARRAY('Name the failure first','Measure a normal week','Keep supplies where the mess happens','Use a backup format'),'sections',JSON_ARRAY(JSON_OBJECT('title','Name the failure','bullets',JSON_ARRAY('Liquid leakage needs coverage and placement.','Litter tracking needs a mat and vacuum routine.','Odor needs sealing and emptying cadence.','Overflow needs a capacity and refill plan.')),JSON_OBJECT('title','Measure the routine','body','Track pads, bags, scoops, refill film, cleaner, and time for seven normal days before changing formats.'),JSON_OBJECT('title','Build the station','checklist',JSON_ARRAY('Keep spare supplies nearby','Place a bin or pail at the actual exit','Add a washable backup surface','Set a refill reminder')),JSON_OBJECT('title','Review after a week','body','If the same failure remains, change the format or placement instead of buying a larger version of the wrong product.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Does odor-control wording guarantee no odor?','a','No. Seals, emptying cadence, cleaning, and room temperature still matter.'),JSON_OBJECT('q','What is the best format for every pet?','a','There is none; dog liquid, cat litter, tracking, and outdoor walks are different workflows.'),JSON_OBJECT('q','Should I buy a backup?','a','A small backup roll or pad pack prevents a delayed delivery from becoming a floor problem.')),'sourceNote','Dimensions and features come from checked Amazon listings; prices, pack counts, and availability change.') WHERE slug='build-a-lower-mess-pet-cleanup-routine';
UPDATE guides SET content_json=JSON_OBJECT('summary','A reliable harness fit starts with measurement, even strap adjustment, a movement check, and a supervised failure-mode test.','takeaways',JSON_ARRAY('Use the current size chart','Measure chest girth accurately','Check elbows, throat, and shoulders','Test backing out indoors'),'sections',JSON_ARRAY(JSON_OBJECT('title','Measure twice','body','Record chest girth and any weight guidance against the exact maker size chart and variant.'),JSON_OBJECT('title','Adjust evenly','checklist',JSON_ARRAY('Two fingers under straps','No rubbing behind elbows','Throat clear','Shoulders move freely')),JSON_OBJECT('title','Test movement','body','Walk indoors, ask the dog to sit and turn, and observe whether the harness rotates or restricts movement.'),JSON_OBJECT('title','Test the failure mode','body','Supervise a gentle backing-out check in a safe room. If the dog can escape, do not use the fit outdoors.')),'faq',JSON_ARRAY(JSON_OBJECT('q','Is two-finger clearance universal?','a','It is a practical starting check, but the current manufacturer chart and the dog’s movement still govern.'),JSON_OBJECT('q','Should I size up for comfort?','a','Not automatically; excess slack can create rubbing or escape risk.'),JSON_OBJECT('q','Can the same harness be used in a car?','a','Only if the exact model instructions document the vehicle setup.')),'sourceNote','Size and feature facts are tied to checked Amazon variants; fit must be tested on the actual dog and current manufacturer instructions.') WHERE slug='measure-and-fit-a-dog-harness';

UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Stop if the blade is hot, jammed, damaged, or the pet is distressed. Do not force through a mat.','intro','Pulling usually means hair intake, coat condition, blade heat, or technique needs to change.','quickChecks',JSON_ARRAY('Turn off and clear hair','Check for mats','Inspect blade and guard','Let the blade cool'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Clear and cool','instruction','Turn the clipper off, remove trapped hair, and let the blade cool before touching the pet.','why','Heat and a jammed blade increase pulling and skin risk.','result','The tool moves freely and is cool.'),JSON_OBJECT('title','Change the pass','instruction','Brush first and take shorter passes with a guard rather than forcing a large amount of coat.','why','Less hair intake reduces stalls and snagging.','result','The coat feeds evenly.'),JSON_OBJECT('title','Inspect maintenance','instruction','Clean and lubricate the blade as directed; replace damaged parts.','why','Buildup and dull edges pull hair.','result','The blade edge and guard are intact.'),JSON_OBJECT('title','Escalate','instruction','Stop for tight mats, skin irritation, repeated stalls, or distress and contact a groomer.','why','Technique cannot make every coat safe to clip at home.','result','The pet avoids unnecessary injury.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Pulling on every pass','cause','Mat or dull blade','next','Stop, brush/clip professionally, inspect blade'),JSON_OBJECT('observation','Stalls after a few seconds','cause','Hair buildup or heat','next','Clear and cool'),JSON_OBJECT('observation','Pet flinches','cause','Heat, noise, or snagging','next','Stop and acclimate or seek help')),'support','Use the current Oneisall instructions and a qualified groomer when the coat or pet tolerance is uncertain.','supportChecklist',JSON_ARRAY('Record guard and blade used','Note coat condition','Keep the ASIN and purchase date'),'faq',JSON_ARRAY(JSON_OBJECT('q','Can oil fix a matted coat?','a','No. Oil supports maintenance; it does not remove a skin-tight mat.'),JSON_OBJECT('q','How often should I cool the blade?','a','Check frequently and whenever the pet shows discomfort.'),JSON_OBJECT('q','Should I keep going if the clipper stalls?','a','No. Turn it off, clear it, and reassess the coat and blade.')),'sourceNote','Tool facts come from the checked Amazon listing; coat and skin problems need professional judgment.') WHERE slug='pet-clipper-pulling-hair';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Clean urine promptly, keep pets away from wet cleaning products, and wash hands after cleanup.','intro','Leaks usually come from orientation, placement, saturation, overlap, or a pet targeting the edge.','quickChecks',JSON_ARRAY('Absorbent side faces up','Pad lies flat','Target area is centered','Pad is replaced before saturation'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Orient the pad','instruction','Place the absorbent surface up with the backing flat and barrier edge unfolded.','why','A folded or reversed pad cannot use its designed coverage.','result','The pad lies smooth with edges visible.'),JSON_OBJECT('title','Move the target','instruction','Observe where the dog stands and place the pad under the actual target area, adding overlap if needed.','why','A large pad still fails if the event lands off its usable area.','result','The event lands away from the edge.'),JSON_OBJECT('title','Replace earlier','instruction','Change the pad before the core saturates and clean beneath it.','why','Saturation and floor residue create secondary leaks.','result','The surface stays dry between events.'),JSON_OBJECT('title','Review the format','instruction','If edge use continues, add a tray or change the routine and consult a veterinarian for sudden changes.','why','A pad cannot solve every behavioral or medical cause.','result','The cleanup format matches the actual problem.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Leak at one edge','cause','Placement or edge use','next','Center and overlap'),JSON_OBJECT('observation','Leak after several events','cause','Saturation','next','Replace earlier'),JSON_OBJECT('observation','Dog avoids pad','cause','Location or texture preference','next','Move it and use positive training')),'support','If accidents change suddenly or come with illness signs, contact a veterinarian.','supportChecklist',JSON_ARRAY('Record pad size and pack variant','Note events per day','Photograph floor damage if contacting support'),'faq',JSON_ARRAY(JSON_OBJECT('q','Does XXL mean leak-proof?','a','No. Coverage and placement still control the result.'),JSON_OBJECT('q','Can I reuse a disposable pad?','a','Follow the product design; reuse can increase leakage and hygiene risk.'),JSON_OBJECT('q','What if the dog targets the edge?','a','Add a tray/overlap or reassess placement and training.')),'sourceNote','Size and barrier claims are scoped to the checked Amazon listing; behavior and health changes require appropriate support.') WHERE slug='training-pad-leaking';
UPDATE troubleshooting_guides SET content_json=JSON_OBJECT('safety','Use a backup identification and control method while fit is uncertain. Stop outdoor use if the harness rubs, shifts, or permits escape.','intro','Rubbing and slipping are fit signals. Adjust evenly, check movement, and test the escape boundary indoors.','quickChecks',JSON_ARRAY('Measure against the current chart','Use two-finger clearance','Clear elbows and throat','Supervise a backing-out test'),'detailedSteps',JSON_ARRAY(JSON_OBJECT('title','Reset the straps','instruction','Loosen and refit the neck and chest straps evenly against the current size chart.','why','One loose strap can rotate the harness and create pressure points.','result','The harness sits centered.'),JSON_OBJECT('title','Check movement','instruction','Walk, sit, turn, and inspect behind elbows and at the throat.','why','Static fit can hide rubbing or shoulder restriction.','result','Movement is free and skin remains clear.'),JSON_OBJECT('title','Test backing out','instruction','In a safe room, apply gentle supervised backward pressure and watch for escape.','why','Body shape and coat can defeat an apparently snug fit.','result','The dog cannot back out under gentle testing.'),JSON_OBJECT('title','Change course','instruction','Stop using the harness outdoors and contact the maker or a qualified fitter if rubbing or slipping remains.','why','Persistent failure is a fit mismatch, not a training shortcut.','result','A safer size or format is selected.')),'causeTable',JSON_ARRAY(JSON_OBJECT('observation','Rubbing behind elbows','cause','Strap too low or loose','next','Refit and recheck movement'),JSON_OBJECT('observation','Harness rotates','cause','Uneven adjustment','next','Center and tighten evenly'),JSON_OBJECT('observation','Dog backs out','cause','Body shape and fit boundary','next','Stop and choose a different fit')),'support','Keep the current Ruffwear size chart and variant details available when contacting support.','supportChecklist',JSON_ARRAY('Record chest measurement','Keep the exact color/size variant','Photograph strap routing if asking for help'),'faq',JSON_ARRAY(JSON_OBJECT('q','Is two-finger clearance enough?','a','It is a starting check; movement and escape testing still matter.'),JSON_OBJECT('q','Should I tighten until the dog cannot move?','a','No. The dog needs normal breathing and shoulder movement.'),JSON_OBJECT('q','Can reflective trim prevent escape?','a','No. Visibility and fit solve different problems.')),'sourceNote','Variant and adjustment facts come from the checked Amazon listing; the actual dog and current size chart determine fit.') WHERE slug='dog-harness-rubs-or-slips';
